#!/bin/bash
set -Eeuo pipefail
umask 077
python3 <<'PYDEPLOY'
from pathlib import Path
import os,stat,json,base64,lzma,subprocess,tempfile,shutil,hashlib
source='4a10d2a70b3f97dc1ecc48624fa716b29200a7af'
subprocess.run(['systemctl','start','celikom-mirror-sync.service'],capture_output=True,timeout=120)
git=['git','-c','safe.directory=/home/celikom-mirror/github-mirror.git','--git-dir=/home/celikom-mirror/github-mirror.git']
subprocess.run(git+['merge-base','--is-ancestor',source,'refs/heads/main'],check=True,capture_output=True,timeout=15)
files=json.loads(lzma.decompress(base64.b64decode('')))
base=Path('/srv/celikom/app/staging-20261122')
specs=[('tools/m4a-normalizer',0o755),('src/Application/M4aNormalizer.php',0o640),('src/Application/UploadService.php',0o640)]
assert hashlib.sha256((base/'src/Application/UploadService.php').read_bytes()).hexdigest()=='82d8fa391e45b2243870d8987b26ccce86cdd4708573b3f6bc0acbb6a428a0cf','LIVE_UPLOAD_SERVICE_CHANGED_REFUSED'
assert hashlib.sha256((base/'src/Application/M4aInspector.php').read_bytes()).hexdigest()=='7b990588837a3b4e7bd03005e6cd1f361e4e53d9060373061a6df227baf2abf8','LIVE_INSPECTOR_CHANGED_REFUSED'
old={};candidates={}
for name,mode in specs:
 p=base/name
 if p.exists():
  st=p.lstat();assert stat.S_ISREG(st.st_mode) and not p.is_symlink();old[name]=(p.read_bytes(),st.st_uid,st.st_gid,stat.S_IMODE(st.st_mode))
 else:assert name!='src/Application/UploadService.php'
 candidates[name]=subprocess.run(git+['show',source+':server/'+name],check=True,capture_output=True,timeout=20).stdout
assert 'tools/m4a-normalizer' not in old and 'src/Application/M4aNormalizer.php' not in old,'UNEXPECTED_EXISTING_M4A_PROCESSOR'
assert hashlib.sha256(candidates['tools/m4a-normalizer']).hexdigest()=='c0f2d9b74c0f1f4e19605d45dbaf3e31e75411a53da4f1ceb172c1e2e0b86d63'
backup=Path(tempfile.mkdtemp(prefix='backend-backup-098-',dir='/srv/celikom-releases/private/extension'))
for name,v in old.items():p=backup/Path(name).name;p.write_bytes(v[0]);p.chmod(0o600)
d=Path(tempfile.mkdtemp(prefix='celikom-m4a98-http-',dir='/tmp'));os.chown(d,0,33);d.chmod(0o750)
replaced=[]
def atomic(p,data,uid,gid,mode):
 fd,tmp=tempfile.mkstemp(prefix='.m4a98-',dir=p.parent)
 try:
  with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
  os.chown(tmp,uid,gid);os.chmod(tmp,mode);os.replace(tmp,p)
 finally:
  if os.path.exists(tmp):os.unlink(tmp)
try:
 for name,mode in specs:
  if name.endswith('.php'):
   p=d/Path(name).name;p.write_bytes(candidates[name]);p.chmod(0o640);os.chown(p,0,33)
   r=subprocess.run(['runuser','-u','www-data','--','php','-l',str(p)],capture_output=True,text=True,timeout=10);assert r.returncode==0,'CANDIDATE_PHP_LINT_FAILED'
 p=d/'probe.php';p.write_text(files['probe']);p.chmod(0o640);os.chown(p,0,33)
 r=subprocess.run(['runuser','-u','www-data','--','php','-l',str(p)],capture_output=True,text=True,timeout=10);assert r.returncode==0,'PROBE_PHP_LINT_FAILED'
 p=d/'fixture.m4a';p.write_bytes(base64.b64decode(files['fixture']));p.chmod(0o640);os.chown(p,0,33)
 for name,mode in specs:
  prior=old.get(name,(None,0,33,mode));atomic(base/name,candidates[name],prior[1],prior[2],prior[3]);replaced.append(name)
 print('M4A_098_DEPLOYED_EXACT_HASHES',json.dumps({k:hashlib.sha256(v).hexdigest() for k,v in candidates.items()}),flush=True)
 r=subprocess.run(['runuser','-u','www-data','--','php',str(d/'probe.php'),str(d/'fixture.m4a')],capture_output=True,text=True,timeout=180)
 print(r.stdout[-9000:],end='',flush=True)
 if r.returncode:print(r.stderr[-1500:]);raise RuntimeError('M4A_HTTP_FLOW_FAILED')
 print('M4A_098_REAL_HTTPS_FLOW_PASS',flush=True)
except BaseException:
 for name in reversed(replaced):
  if name in old:atomic(base/name,*old[name])
  else:(base/name).unlink()
 print('M4A_098_ROLLED_BACK',flush=True);raise
finally:shutil.rmtree(d)
PYDEPLOY

python3 <<'PYBUILD'
import subprocess,json,posixpath,urllib.request,hashlib,lzma,shutil
from pathlib import Path
source="4a10d2a70b3f97dc1ecc48624fa716b29200a7af"
git=["git","-c","safe.directory=/home/celikom-mirror/github-mirror.git","--git-dir=/home/celikom-mirror/github-mirror.git"]
subprocess.run(git+["merge-base","--is-ancestor",source,"refs/heads/main"],check=True,capture_output=True,timeout=15)
runner_uid=str(Path("/srv/celikom/ci-runner/runner/celikom-build-spool").stat().st_uid)
assert runner_uid!="0"
print("EXTENSION_098_ACTUAL_SPOOL_OWNER_UID",runner_uid)
base=["docker","exec","--user",runner_uid,"celikom-floki-ci01"]
node='/home/runner/_work/_tool/node/24.22.3/x64/bin/node'
r=subprocess.run(base+[node,'--version'],capture_output=True,text=True,check=True,timeout=10)
assert r.stdout.startswith('v24.')

r=subprocess.run(base+["mktemp","-d","/home/runner/celikom-build-spool/.work-extension98-owner.XXXXXXXX"],capture_output=True,text=True,check=True,timeout=15)
directory=r.stdout.strip()
assert directory.startswith("/home/runner/celikom-build-spool/.work-extension98-owner.") and directory.count("/")==4
archive=subprocess.run(git+["archive",source,"extension","scripts","package.json","package-lock.json","server/composer.json",".github/scripts/floki-private-build-spool.mjs"],capture_output=True,check=True,timeout=60).stdout
assert len(archive)<64*1024*1024
subprocess.run(["docker","exec","-i","--user",runner_uid,"celikom-floki-ci01","tar","-xf","-","-C",directory],input=archive,check=True,capture_output=True,timeout=30)
js=r"""
import {spawnSync} from 'node:child_process';
import {readdirSync,readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {createHash} from 'node:crypto';
import path from 'node:path';
mkdirSync('.temporary',{recursive:true});
const env={...process.env,TMPDIR:path.resolve('.temporary'),CELIKOM_API_BASE_URL:'https://api.celikom.com',PATH:path.dirname(process.execPath)+':'+process.env.PATH};
function run(args){
 const r=spawnSync(process.execPath,args,{env,encoding:'utf8',timeout:240000,maxBuffer:8*1024*1024});
 if(r.status!==0){console.log((r.stdout||'').slice(-3500),(r.stderr||'').slice(-2000));throw Error('ISOLATED_BUILD_CHECK_FAILED');}
 console.log((r.stdout||'').slice(-1200));
 return r.stdout||'';
}
run(['--disable-warning=ExperimentalWarning','extension/scripts/build.mjs','--unpacked-only']);
const tests=readdirSync('extension/tests').filter(x=>x.endsWith('.test.mjs')).map(x=>'extension/tests/'+x);
const report=run(['--test','--test-concurrency=2',...tests]);
if(!/pass 510/.test(report))throw Error('EXPECTED_510_TESTS');
run(['--disable-warning=ExperimentalWarning','extension/scripts/build.mjs']);
run(['extension/scripts/validate-manifest.mjs']);
run(['scripts/security-audit.mjs']);
const zip=readFileSync('extension/dist/celikom-extension-0.4.98.zip');
const sha=createHash('sha256').update(zip).digest('hex');
if(zip.length!==2507773||sha!=='76d190f9af494afb1634c873d1e734dd0a5944a64a326f32715d89e03daaa63d')throw Error('PACKAGE_MISMATCH');
writeFileSync('private-owner-build-verified.json',JSON.stringify({source:'4a10d2a70b3f97dc1ecc48624fa716b29200a7af',tests:510,size:zip.length,sha256:sha}));
console.log('EXTENSION_098_ISOLATED_BUILD_CHECKS_PASS',sha,zip.length);
"""
r=subprocess.run(["docker","exec","-i","--user",runner_uid,"--workdir",directory,"celikom-floki-ci01",node,"--input-type=module","-"],input=js,capture_output=True,text=True,timeout=600)
print(r.stdout[-12000:],end="")
assert r.returncode==0,"UNPRIVILEGED_EXTENSION_BUILD_FAILED"
print("EXTENSION_098_ISOLATED_BUILD_LOCATION",json.dumps({"directory":directory,"node":node,"source":source}))
PYBUILD
